function() {
  var el = {{Click Element}};
  if (!el || !el.closest) { return 'unknown'; }

  // Explicit marker wins: SiteHeader, SiteFooter, Hero and CallToAction each
  // carry data-cta-location on their root element.
  var marked = el.closest('[data-cta-location]');
  if (marked) { return marked.getAttribute('data-cta-location') || 'unknown'; }

  // Fallback for every other section component: the nearest landmark's first
  // class is its BEM block, which is 1:1 with the component name
  // (stat-band, service-blocks, pathway, story, testimonials, ...).
  var sec = el.closest('section, header, footer, aside, nav');
  if (sec && typeof sec.className === 'string') {
    var first = sec.className.trim().split(/\s+/)[0];
    if (first) { return first.replace(/-/g, '_'); }
  }
  return 'unknown';
}
